script.text:

function load$GridReport$(g) {g.add_onRender(on$GridReport$Render);}
function dispose$GridReport$(g) {try {g.remove_onRender(on$GridReport$Render);} catch (ex) {}}
function on$GridReport$Render(sender, eventArgs) {
	var g = eventArgs.grid;  
	if (g._hiddenFields) {    
		var a = g._hiddenFields, h = '';
		for (var i = 0; i < a.length; i++) {
			setGridHiddenFields(g, a[i].Fields, a[i].Value);
			if (a[i].Value) h += (h == '' ? '' : ',') + a[i].Fields;
		}
		g._externalHiddenFields = h;
	}
	setHeaderLevel(2, 3);
	setColorWithCondition(g, 'stt', '0', '', 700, '');
}
function setGridHiddenFields(g, c, v) {
	var a = c.split(',');
	for (var i = 0; i < a.length; i++) {
		var l = g._getColumnOrder($func.trim(a[i]));
		if (l != -1) g._setColumnVisible(l, !v);
	}
}
function beforeDrillDown(g) {g._args.cancelEvent = !($func.trim(g._getItemValue(g._activeRow, g._activeColumn)));}
function formatDateView(c) {return String.format('{0}/{1}/{2}', c.substring(6, 8), c.substring(4, 6), c.substring(0, 4));}
function setHeaderLevel(level, elevate)
{
	var tagHeader = document.getElementById("ctl00_FastBusiness_MainReport_gridHeader").firstChild;
	var arCell = tagHeader.firstChild.cells;	
	var xid = 0;
	for(var i = 0; i < arCell.length; i++){
		if(arCell[i].style.display != "none")
			arCell[i].setAttribute("xid", xid++);		

		var arA = arCell[i].getElementsByTagName("a");
		for(var j = 0; j < arA.length; i++){
			var title = arA[j].getAttribute("title");
			if(title != null){
				arA[j].setAttribute("title", title.split("<label")[0]);
				break;
			}
		}
	}
	var sRow = "";
	for(var i = 1; i <= level; i++)
		sRow += getRowMerge(arCell, "h" + i)


	var tagTable = document.getElementById("ctl00_FastBusiness_MainReport_gridHeader");
	var th = document.createElement("thead");
	th.innerHTML = sRow;
	tagTable.insertBefore(th, tagTable.firstChild);
	var rpBody = document.getElementById("ctl00_FastBusiness_MainReport_divGrid");
	rpBody.style.height = (rpBody.offsetHeight - (20*level)) + "px";

	if(!document.getElementById("header_merge_css")){
		var xHeight = 20*(level+elevate)+ 18;
		var css = document.createElement("style");
		css.type = "text/css";
		css.id = "header_merge_css";
		css.innerHTML = ".HeaderCellDefault > .RowBottom{height: " + xHeight + "px !important;} .IndexCellHeader > .RowBottom{height: " + (xHeight + 4) + "px !important;} .HeaderMergeHidden > span{display: none;}";
		document.body.appendChild(css);
	}
	hiddenMergeFreeze();
	document.getElementById("ctl00_FastBusiness_MainReport_ToolbarButton_Freeze").addEventListener("click", function(){
		 hiddenMergeFreeze();
	});
}


function getRowMerge(arCell, attr){
	var sTd = "", iCol = arCell.length, xid = 0;
	try{
		for(var i = 0; i < iCol; i++){
			var cid = arCell[i].getAttribute("xid");
			var arLabel = arCell[i].getElementsByTagName("label");
			if(arCell[i].style.display != "none" && cid == xid){
				if(arLabel.length > 0 && arLabel[0].hasAttribute(attr)){
					var arH = arLabel[0].getAttribute(attr).split("|");
					var cSpan = parseInt(arH[0]);
					var endMerge = parseInt(cid) + cSpan - 1;
					sTd += '<td class="IndexCellHeader" name="header_merge_' + endMerge + '" colspan="' + cSpan + '" style="text-align: center;"><span style="color: #696969; max-width: 200px; display: block; overflow-x:auto; ">'+ arH[1].replaceAll(String.fromCharCode('254'), '<br />') + '</span></td>';

					i += cSpan - 1;
					xid = parseInt(cid) + cSpan;
				}
				else{
					sTd += '<td class="IndexCellHeader " style="border-bottom: none;"></td>';
					xid++;
				}
			}
		}
	}
	catch(e){
		alert(attr + " : " + e.message);
	}

	return '<tr style="height:20px;" id="ctl00_FastBusiness_MainReport_gridHeader" class="GridHeader">' + sTd + '</tr>';;
}

function hiddenMergeFreeze(){

	var arMerge = document.getElementsByClassName("HeaderCellContainer GridHeader RowBottom");
	if(arMerge.length > 0){
		for(var i = 0; i < arMerge.length; i++){
			var mID = "header_merge_" + arMerge[i].parentNode.getAttribute("xid");

			if(mID){
				var arC = document.getElementsByName(mID);
				for(var j = 0; j < arC.length; j++)
					arC[j].className += " HeaderMergeHidden";
			}
		}
	}
	else{
		var arM = document.getElementsByClassName("HeaderMergeHidden");
		for(var k = 0; k < arM.length; k++)
			arM[k].className = "IndexCellHeader";
	}
}

&zSetReportColorJS;
